// StillaEdge v2.7 kinds: setup | alignment | outcome | report | snapshot | calendar
const b = $json.body || $json;
const tf = String(b.tf || '').replace('PERIOD_', '');
const kind = b.kind || 'setup';

// ---------- AI kinds: build a prompt, AI branch handles the rest ----------
if (kind === 'snapshot') {
  const prompt =
    `You are an experienced forex technical analyst. Using ONLY the JSON data below, ` +
    `write a concise intraday analysis in Burmese (Myanmar language). Keep all technical ` +
    `terms in English (support, resistance, momentum, trend, breakout, confluence, ATR, RR). ` +
    `Structure EXACTLY as four short sections, each on its own lines:\n` +
    `Bias: LONG / SHORT / NEUTRAL — one-line reason\n` +
    `ဦးစားပေး scenario: which key level holds, what target zones follow (use the zone prices in the data)\n` +
    `Alternative scenario: if that key level breaks, which levels come next\n` +
    `Comment: evidence from the data (trend states, momentum, alignment, zone bounce rates)\n` +
    `Rules: under 120 words. Plain text only, no markdown symbols (no ** or #). ` +
    `NEVER invent price levels that are not in the data. If alignment is MIXED, bias must be NEUTRAL.\n` +
    `DATA: ${JSON.stringify(b)}`;
  return [{ json: { route: 'ai', prompt, header: `📈 <b>${b.symbol} Market Analysis</b> (${b.time || ''})` } }];
}

if (kind === 'calendar') {
  const prompt =
    `You are preparing a daily economic-calendar briefing for a Myanmar forex trader. ` +
    `All event times in the data are ALREADY in Myanmar time (Asia/Yangon). ` +
    `Write in Burmese, keep event names in English. Start with ONE sentence saying which ` +
    `currencies/sessions need caution today. Then list events ordered by time, one line each:\n` +
    `HH:MM 🔴 USD — Event Name (very short Burmese note)\n` +
    `Use 🔴 for HIGH importance and 🟡 for MODERATE. Under 150 words. Plain text, no markdown.\n` +
    `DATA: ${JSON.stringify(b)}`;
  return [{ json: { route: 'ai', prompt, header: `📅 <b>တစ်နေ့တာ သတင်းထုတ်ပြန်မှုဇယား</b> (${b.date || ''})` } }];
}

// ---------- direct kinds: format the final message here ----------
let message = '';

if (kind === 'alignment') {
  const icon = b.side === 'BULL' ? '🟢📈' : '🔴📉';
  message =
    `🔥 <b>STRONG TREND ALIGNMENT</b>\n` +
    `📊 ${b.symbol}\n` +
    `${icon} Direction: <b>${b.side}</b>\n` +
    `(1D/4H/1H trend + 15M/30M momentum aligned)\n` +
    `🕐 ${b.time}`;

} else if (kind === 'outcome') {
  const win = b.result === 'WIN';
  const icon = win ? '✅' : '❌';
  const hrs = (Number(b.hold_min || 0) / 60).toFixed(1);
  message =
    `${icon} <b>Setup ${b.result}</b>\n` +
    `📊 ${b.symbol} ${tf} — ${b.side}\n` +
    `Entry ${b.entry} → Exit ${b.exit}\n` +
    `📐 ${b.r}R | Score was ${b.score}% | held ${hrs}h\n` +
    `🕐 ${b.time}`;

} else if (kind === 'report') {
  const closed = Number(b.closed || 0);
  const bar = closed > 0
    ? '🟩'.repeat(Number(b.wins)) + '🟥'.repeat(Number(b.losses))
    : '—';
  message =
    `📋 <b>StillaEdge Daily Report</b>\n` +
    `📊 ${b.symbol} ${tf}\n` +
    `Closed today: <b>${b.closed}</b>  ${bar}\n` +
    `✅ ${b.wins} WIN / ❌ ${b.losses} LOSS` +
    (closed > 0 ? ` (${b.winrate}%)` : '') + `\n` +
    `⏳ Still open: ${b.open}\n` +
    `📈 Since attach: ${b.total_wins}W / ${b.total_losses}L\n` +
    `🕐 ${b.time}`;

} else {
  const icon = b.side === 'BUY' ? '📈' : '📉';
  const risk = Math.abs(Number(b.entry) - Number(b.sl));
  const reward = Math.abs(Number(b.tp) - Number(b.entry));
  const rr = risk > 0 ? (reward / risk).toFixed(1) : '?';
  message =
    `🔔 <b>StillaEdge Setup</b>\n` +
    `📊 ${b.symbol} ${tf}\n` +
    `${icon} <b>${b.side}</b> @ ${b.entry}\n` +
    `🛑 SL: ${b.sl}\n` +
    `🎯 TP: ${b.tp}\n` +
    `⚖️ RR 1:${rr} | Score: ${b.score}%\n` +
    `🕐 ${b.time}\n` +
    `<i>Stats-based guide — confirm on chart before entry.</i>`;
}

return [{ json: { route: 'direct', message } }];

// Attach header + fixed Burmese disclaimer. Never trust the model to include it.
const header = $('Route & Format').item.json.header || '';
let t = $json.text ?? $json.output ?? $json.response ?? '';
t = String(t).trim()
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const disclaimer =
  '\n\n<i>မှတ်ချက်။ ။ အထက်ပါ သုံးသပ်ချက်များသည် AI မှ EA ပေးပို့သော market data ပေါ်အခြေခံ၍ သုံးသပ်ထားခြင်းသာဖြစ်ပြီး ရေးသားသူ AI ၏ တစ်ဦးတည်းအမြင်သာ ဖြစ်ပါသည်။ Market သုံးသပ်ချက် မှားယွင်းနိုင်ပါသဖြင့် အပြည့်အဝ မယုံကြည်ဘဲ တစ်စိတ်တစ်ပိုင်း အထောက်အကူအဖြစ်သာ အသုံးပြုပါရန်။</i>';
return [{ json: { message: header + '\n\n' + t + disclaimer } }];
